/**
 * Official IRIS Brand Logo Data URIs (Tightly Cropped, Zero-Margin)
 * Embedded as inline Base64 PNGs to guarantee 100% resilient loading across
 * Vite dev mode, Electron packaged file:// builds, and nativeImage windows.
 */

export const IRIS_LOGO_WHITE_DATA_URL = 'data:image/png;base64,';

export const IRIS_LOGO_BLACK_DATA_URL = 'data:image/png;base64,';

export function getIrisLogoDataUri(isDark?: boolean): string {
  return isDark ? IRIS_LOGO_WHITE_DATA_URL : IRIS_LOGO_BLACK_DATA_URL;
}

export default IRIS_LOGO_WHITE_DATA_URL;
